/* Test Case 1: Trigger replace_existing by adding two cookies with same name/domain/path */
static void test_replace_existing(void)
{
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init failed\n");
        return;
    }

    struct CookieInfo *ci = Curl_cookie_init(curl, NULL, NULL, TRUE);
    if (!ci) {
        fprintf(stderr, "Curl_cookie_init failed\n");
        curl_easy_cleanup(curl);
        return;
    }

    /* Add first cookie (secure) */
    const char *cookie1 = "Set-Cookie: test=value1; domain=example.com; path=/; secure";
    struct Cookie *co1 = Curl_cookie_add(curl, ci, TRUE, FALSE, cookie1, "example.com", "/", TRUE);
    if (!co1) {
        fprintf(stderr, "First cookie add failed\n");
    } else {
        printf("First cookie added successfully\n");
    }

    /* Add second cookie with same name/domain/path but non-secure - should trigger replacement logic */
    const char *cookie2 = "Set-Cookie: test=value2; domain=example.com; path=/";
    struct Cookie *co2 = Curl_cookie_add(curl, ci, TRUE, FALSE, cookie2, "example.com", "/", FALSE);
    if (!co2) {
        fprintf(stderr, "Second cookie add failed (may be expected due to secure overlay check)\n");
    } else {
        printf("Second cookie added successfully\n");
    }

    /* Add third cookie with same name/domain/path - should trigger replace_existing */
    const char *cookie3 = "Set-Cookie: test=value3; domain=example.com; path=/; secure";
    struct Cookie *co3 = Curl_cookie_add(curl, ci, TRUE, FALSE, cookie3, "example.com", "/", TRUE);
    if (!co3) {
        fprintf(stderr, "Third cookie add failed\n");
    } else {
        printf("Third cookie added successfully\n");
    }

    Curl_cookie_cleanup(ci);
    curl_easy_cleanup(curl);
}

/* Test Case 2: Trigger error paths in Curl_cookie_add with malformed cookies */
static void test_malformed_cookies(void)
{
    CURL *curl = curl_easy_init();
    if (!curl) {
        fprintf(stderr, "curl_easy_init failed\n");
        return;
    }

    struct CookieInfo *ci = Curl_cookie_init(curl, NULL, NULL, TRUE);
    if (!ci) {
        fprintf(stderr, "Curl_cookie_init failed\n");
        curl_easy_cleanup(curl);
        return;
    }

    /* Test various malformed cookie lines that should trigger error paths */
    const char *malformed_cookies[] = {
        /* Missing name */
        "Set-Cookie: =value; domain=example.com; path=/",
        /* Bad domain */
        "Set-Cookie: test=value; domain=; path=/",
        /* Tab in value (should trigger CERR_TAB) */
        "Set-Cookie: test=val\tue; domain=example.com; path=/",
        /* Invalid expires */
        "Set-Cookie: test=value; expires=invalid; domain=example.com; path=/",
        /* Max-age overflow */
        "Set-Cookie: test=value; max-age=99999999999999999999; domain=example.com; path=/",
        /* Bad path */
        "Set-Cookie: test=value; path=invalid; domain=example.com",
        /* No domain or path */
        "Set-Cookie: test=value",
        NULL
    };

    for (int i = 0; malformed_cookies[i]; i++) {
        printf("Testing malformed cookie %d: %s\n", i, malformed_cookies[i]);
        struct Cookie *co = Curl_cookie_add(curl, ci, TRUE, FALSE, malformed_cookies[i], "example.com", "/", TRUE);
        if (co) {
            printf("  Unexpectedly succeeded\n");
        } else {
            printf("  Failed as expected\n");
        }
    }

    Curl_cookie_cleanup(ci);
    curl_easy_cleanup(curl);
}

