      retcode = NETRC_FAILED;
      goto out;
    }
  }
  else {
    bool escape = FALSE;
    bool endquote = FALSE;
    tok_end++; /* pass the leading quote */
    while(*tok_end) {
      char s = *tok_end;
      if(escape) {
        escape = FALSE;
        switch(s) {
        case 'n':
          s = '\n';
          break;
        case 'r':
          s = '\r';
          break;
        case 't':
          s = '\t';
          break;
        }
      }
      else if(s == '\\') {
        escape = TRUE;
        tok_end++;
        continue;
      }
      else if(s == '\"') {
        tok_end++; /* pass the ending quote */
        endquote = TRUE;
        break;
      }
      if(Curl_dyn_addn(&token, &s, 1)) {
        retcode = NETRC_FAILED;
        goto out;
      }
      tok_end++;
    }
    if(escape || !endquote) {
      /* bad syntax, get out */
      retcode = NETRC_FAILED;
      goto out;
    }
  }

  tok = Curl_dyn_ptr(&token);

  switch(state) {
  case NOTHING:
    if(strcasecompare("macdef", tok))
      /* Define a macro. A macro is defined with the specified name; its
         contents begin with the next .netrc line and continue until a
         null line (consecutive new-line characters) is encountered. */
      state = MACDEF;
    else if(strcasecompare("machine", tok)) {
      /* the next tok is the machine name, this is in itself the delimiter
         that starts the stuff entered for this machine, after this we
         need to search for 'login' and 'password'. */
      state = HOSTFOUND;
      keyword = NONE;
      found = 0;
      our_login = FALSE;
      Curl_safefree(password);
      if(!specific_login)
