    }
    else if(strcasecompare("default", tok)) {
      state = HOSTVALID;
      retcode = NETRC_SUCCESS; /* we did find our host */
    }
    break;
  case MACDEF:
    if(!*tok)
      state = NOTHING;
    break;
  case HOSTFOUND:
    if(strcasecompare(host, tok)) {
      /* and yes, this is our host! */
      state = HOSTVALID;
      retcode = NETRC_SUCCESS; /* we did find our host */
    }
    else
      /* not our host */
      state = NOTHING;
    break;
