/*
 * Copies a filename part and returns an ALLOCATED data buffer.
 */
static char *parse_filename(const char *ptr, size_t len, char stop)
{
  char *copy;
  char *p;
  char *q;

  copy = curlx_memdup0(ptr, len);
  if(!copy)
    return NULL;

  p = copy;
  if(stop) {
    /* a Conten
... [500 chars cut] ...

      *q = '\0';
  }

  /* if the filename contains a path, only use filename portion */
  q = strrchr(p, '/');
  if(q) {
    p = q + 1;
    if(!*p) {
      curlx_safefree(copy);
      return NULL;
    }
  }

  /* If the filename contains a backslash, only use filename portion. The idea
     is that even systems that do not handle backslashes as path separators
     probably want the path removed for convenience. */
  q = strrchr(p, '\\');
  if(q) {
    p = q + 1;
    if(!*p) {
      curlx_safefree(copy);
      return NULL;
    }
  }

  /* make sure the filename does not end in \r or \n */
  q = strchr(p, '\r');
  if(q)
    *q = '\0';

  q = strchr(p, '\n');
  if(q)
    *q = '\0';

  if(copy != p)
    memmove(copy, p, strlen(p) + 1);

#if defined(_WIN32) || defined(MSDOS)
  {
    char *sanitized;
    SANITIZEcode sc = sanitize_file_name(&sanitized, copy, 0);
    curlx_safefree(copy);
    if(sc)
      return NULL;
    copy = sanitized;
  }
#endif /* _WIN32 || MSDOS */

  return copy;
}

int tool_write_headers(struct HdrCbData *hdrcbdata, FILE *stream)
{
  struct curl_slist *h = hdrcbdata->headlist;
  int rc = 1;
  while(h) {
    /* not "handled", show it */
    size_t len = strlen(h->data);
    if(len != fwrite(h->data, 1, len, stream))
      goto fail;
    h = h->next;
  }
  rc = 0; /* success */
fail:
  curl_slist_free_all(hdrcbdata->headlist);
  hdrcbdata->headlist = NULL;
  return rc;
}

/*
 * Write etag to file when --etag-save option is given.
 */
static size_t save_etag(const char *etag_h, const char *endp,
                        struct OutStruct *etag_save)
{
  const char *eot = endp - 1;
  if(*eot == '\n') {
    while(ISBLANK(*etag_h) && (etag_h < eot))
      etag_h++;
    while(ISSPACE(*eot))
      eot--;

    if(eot >= etag_h) {
      size_t etag_length = eot - etag_h + 1;
      curlx_struct_stat file;
      int fd = fileno(etag_save->stream);

      /* Truncate regular files to avoid stale etag content */
      if((fd != -1) &&
         etag_save->regular_file &&
         !curlx_fstat(fd, &file) &&
         (S_ISREG(file.st_mode) &&
          toolx_ftruncate(fd, 0)))
        return CURL_WRITEFUNC_ERROR;

      fwrite(etag_h, 1, etag_length, etag_save->stream);
      /* terminate with newline */
      fputc('\n', etag_save->stream);
      (void)fflush(etag_save->stream);
    }
  }
  return 0; /* ok */
}

static bool set_filename(struct OutStruct *outs,
                         struct per_transfer *per, char *filename)
{
  if(outs->stream) {
    /* indication of problem, get out! */
    curlx_free(filename);
    return FALSE;
  }
  if(outs->alloc_filename)
    curlx_safefree(outs->filename);

  if(per->config->output_dir) {
    char *f = curl_maprintf("%s/%s", per->config->output_dir, filename);
    curlx_free(filename);
    if(!f)
      return FALSE;
    outs->filename = curlx_strdup(f);
    curl_free(f);
    if(!outs->filename)
      return FALSE;
  }
  else
    outs->filename = filename;
  return TRUE;
}

