#include <curl/curl.h>
#include <stdio.h>
#include <stdlib.h>

int main(void)
{
  CURL *easy;
  curl_mime *root;
  curl_mime *current;
  int i;
  int depth = 5000;

  curl_global_init(CURL_GLOBAL_ALL);
  easy = curl_easy_init();
  root = curl_mime_init(easy);
  current = root;
  if(!easy || !root) {
    fprintf(stderr, "Failed to init curl or mime\n");
    return 1;
  }

  for(i = 0; i < depth; i++) {
    curl_mimepart *part = curl_mime_addpart(current);
    curl_mime *child = curl_mime_init(easy);
    if(!part || !child) {
      fprintf(stderr, "Failed at depth %d\n", i);
      return 1;
    }
    curl_mime_subparts(part, child);
    current = child;
  }
  printf("freeing %d nested MIME levels\n", depth);
  fflush(stdout);
  curl_mime_free(root);
  curl_easy_cleanup(easy);
  curl_global_cleanup();
  printf("Done\n");
  return 0;
}

